selector_to_html = {"a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Software requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>Only PyTorch is required for the local PyTorch path. Every integration is an\noptional extra, so the minimal installation stays small and imports lazily.</p>", "a[href=\"../user_guide/training.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Training with PyTorch<a class=\"headerlink\" href=\"#training-with-pytorch\" title=\"Link to this heading\">#</a></h1><p>Execution and training are intentionally separate. <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code> owns the\ntrainable quantum parameters, circuit builder, observable selection, runtime\npolicy, and precision, while <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.train</span></code> is a minimal optimizer loop you can\nreplace with your own.</p>", "a[href=\"../user_guide/basic-usage.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h1><h2>Build a circuit<a class=\"headerlink\" href=\"#build-a-circuit\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_qubits</span></code> is the preferred public name for circuit size. Positional\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit(2)</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=2</span></code>, and the legacy <code class=\"docutils literal notranslate\"><span class=\"pre\">nqubits=2</span></code> remain compatible, and\nconflicting aliases fail during construction. Internal IR, compiler, and runtime\nmappings continue to use <em>wire</em> for logical mappings.</p><p>Generated gate methods keep their concise positional form and also accept\nsemantic qubit keywords: <code class=\"docutils literal notranslate\"><span class=\"pre\">h(0)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">h(qubit=0)</span></code> are equivalent, <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(0,</span> <span class=\"pre\">1)</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">cx(control=0,</span> <span class=\"pre\">target=1)</span></code> are equivalent, symmetric two-qubit gates use\n<code class=\"docutils literal notranslate\"><span class=\"pre\">qubit1=</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit2=</span></code>, and the generic <code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit.gate(...)</span></code> keeps <code class=\"docutils literal notranslate\"><span class=\"pre\">wires=</span></code>.\nDuplicate, conflicting, or missing qubit arguments fail before an instruction is\nadded.</p>", "a[href=\"#run-a-first-execution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Run a first execution<a class=\"headerlink\" href=\"#run-a-first-execution\" title=\"Link to this heading\">#</a></h2><p>The example runs one complete local journey: build a circuit, create an\ninspectable plan, execute that plan on the CPU statevector engine, and compare\nthe result with an analytical reference. The three smallest maintained programs\nare:</p>", "a[href=\"#optional-development-containers\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Optional development containers<a class=\"headerlink\" href=\"#optional-development-containers\" title=\"Link to this heading\">#</a></h2><p>The repository ships development container definitions for a CPU image, a\nCUDA image, and variants without JAX that carry QSteed and the compiler plugin\nin one environment. They are the recommended way to reproduce the tutorial and\ninteroperability dependency sets. See the container guide in the repository for\nthe image list and launch commands.</p>", "a[href=\"#install-flagquantum\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagQuantum<a class=\"headerlink\" href=\"#install-flagquantum\" title=\"Link to this heading\">#</a></h1><p>Read <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a> before proceeding.</p>", "a[href=\"#migrating-from-the-pre-release-v0-1-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Migrating from the pre-release v0.1 API<a class=\"headerlink\" href=\"#migrating-from-the-pre-release-v0-1-api\" title=\"Link to this heading\">#</a></h2><p>The v0.1 <code class=\"docutils literal notranslate\"><span class=\"pre\">DistributedQuantumDevice</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">GeneralEncoder</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">InvertibleUnitary</span></code>,\nDTensor interchange helpers, device-oriented gates, and the device-oriented\nmeasurement path are not part of the v0.2 product and have no compatibility\nlayer. Port those programs to <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Circuit</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.plan</span></code>, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code>; see <a class=\"reference internal\" href=\"../user_guide/basic-usage.html\"><span class=\"std std-doc\">Basic Usage</span></a> and\n<a class=\"reference internal\" href=\"../user_guide/training.html\"><span class=\"std std-doc\">Training</span></a>.</p>", "a[href=\"#verify-the-installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Verify the installation<a class=\"headerlink\" href=\"#verify-the-installation\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Install FlagQuantum<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>The released version from PyPI:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
